const SITE={"yt": "https://youtube.com/@WiggleStudioo", "groups": [{"title": "Little components", "emoji": "🍬", "desc": "Small things from my Shorts. Paste them into any project.", "video": "", "short": "", "zip": "", "items": [{"id": "login", "emoji": "🌸", "title": "Animated Login Form", "desc": "Floating labels and a show/hide password button.", "tags": ["HTML", "CSS"], "video": "https://youtube.com/shorts/CYlmh0Jl6sY", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Animated Login Form</title>\n  <style>\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    body {\n      min-height: 100vh;\n      display: grid;\n      place-items: center;\n      font-family: \"Poppins\", system-ui, sans-serif;\n      font-size: 18px;\n      color: #e8eaf6;\n      background: radial-gradient(circle at 20% 15%, #2d1757, #0b0d17 60%);\n    }\n    .card {\n      width: 460px;\n      padding: 46px 40px;\n      border-radius: 26px;\n      background: rgba(21, 26, 46, .85);\n      border: 1px solid rgba(255, 120, 190, .25);\n      box-shadow: 0 24px 70px rgba(0, 0, 0, .55);\n    }\n    h1 { font-size: 36px; margin-bottom: 6px; }\n    .sub { color: #8b90b0; font-size: 16px; margin-bottom: 32px; }\n    .field { position: relative; margin-bottom: 24px; }\n    .field input {\n      width: 100%;\n      padding: 24px 46px 10px 16px;\n      border-radius: 14px;\n      border: 1px solid #2a3050;\n      background: #0f1324;\n      color: #e8eaf6;\n      font: inherit;\n      outline: none;\n      transition: border-color .3s, box-shadow .3s;\n    }\n    .field label {\n      position: absolute;\n      left: 16px;\n      top: 17px;\n      color: #8b90b0;\n      pointer-events: none;\n      transition: all .25s;\n    }\n    input:focus + label,\n    input:not(:placeholder-shown) + label {\n      top: 6px;\n      font-size: 12px;\n      color: #ff78be;\n    }\n    input:focus {\n      border-color: #ff78be;\n      box-shadow: 0 0 0 4px rgba(255, 120, 190, .18);\n    }\n    .eye {\n      position: absolute;\n      right: 14px;\n      top: 16px;\n      background: none;\n      border: none;\n      color: #8b90b0;\n      font-size: 18px;\n      cursor: pointer;\n    }\n    .btn {\n      width: 100%;\n      padding: 16px;\n      border: none;\n      border-radius: 14px;\n      font: inherit;\n      font-weight: 600;\n      color: #0b0d17;\n      cursor: pointer;\n      background: linear-gradient(90deg, #ff78be, #78dcff);\n      transition: transform .2s, box-shadow .2s;\n    }\n    .btn:hover {\n      transform: translateY(-3px);\n      box-shadow: 0 12px 32px rgba(255, 120, 190, .4);\n    }\n    .btn.done { background: linear-gradient(90deg, #4ade80, #78dcff); }\n    .foot { text-align: center; margin-top: 22px; font-size: 15px; color: #8b90b0; }\n    .foot a { color: #78dcff; text-decoration: none; }\n  </style>\n</head>\n<body>\n  <form class=\"card\" id=\"form\">\n    <h1>Welcome back</h1>\n    <p class=\"sub\">Log in to continue</p>\n\n    <div class=\"field\">\n      <input type=\"email\" id=\"email\" placeholder=\" \" required>\n      <label for=\"email\">Email</label>\n    </div>\n\n    <div class=\"field\">\n      <input type=\"password\" id=\"pass\" placeholder=\" \" required>\n      <label for=\"pass\">Password</label>\n      <button type=\"button\" class=\"eye\" id=\"eye\">👁</button>\n    </div>\n\n    <button class=\"btn\" id=\"btn\" type=\"submit\">Log in</button>\n    <p class=\"foot\">New here? <a href=\"#\">Create account</a></p>\n  </form>\n\n  <script>\n    const pass = document.getElementById(\"pass\");\n    const eye = document.getElementById(\"eye\");\n    const form = document.getElementById(\"form\");\n    const btn = document.getElementById(\"btn\");\n\n    // show / hide password\n    eye.onclick = () => {\n      pass.type = pass.type === \"password\" ? \"text\" : \"password\";\n    };\n\n    // fake login (no server), just a happy message\n    form.onsubmit = (e) => {\n      e.preventDefault();\n      btn.textContent = \"Welcome back ✓\";\n      btn.classList.add(\"done\");\n    };\n  </script>\n</body>\n</html>\n", "dl": "demos/login.html"}, {"id": "otp", "emoji": "🍓", "title": "OTP Input Boxes", "desc": "Auto-jumping boxes that check the code. Try 1234!", "tags": ["HTML", "CSS", "JS"], "video": "https://youtube.com/shorts/RfwfxwMYtv4", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>OTP Input Box</title>\n  <style>\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    body {\n      min-height: 100vh;\n      display: grid;\n      place-items: center;\n      font-family: \"Poppins\", system-ui, sans-serif;\n      font-size: 18px;\n      color: #e8eaf6;\n      background: radial-gradient(circle at 80% 10%, #2d1757, #0b0d17 60%);\n    }\n    .card {\n      width: 520px;\n      padding: 50px 40px;\n      text-align: center;\n      border-radius: 26px;\n      background: rgba(21, 26, 46, .85);\n      border: 1px solid rgba(120, 220, 255, .25);\n      box-shadow: 0 24px 70px rgba(0, 0, 0, .55);\n    }\n    h1 { font-size: 34px; margin-bottom: 8px; }\n    p { color: #8b90b0; font-size: 16px; }\n    .boxes { display: flex; justify-content: center; gap: 16px; margin: 38px 0 26px; }\n    .boxes input {\n      width: 76px;\n      height: 92px;\n      text-align: center;\n      font: inherit;\n      font-size: 38px;\n      font-weight: 600;\n      color: #e8eaf6;\n      background: #0f1324;\n      border: 2px solid #2a3050;\n      border-radius: 16px;\n      outline: none;\n      transition: border-color .25s, box-shadow .25s, transform .25s;\n    }\n    .boxes input:focus {\n      border-color: #ff78be;\n      box-shadow: 0 0 0 5px rgba(255, 120, 190, .18);\n      transform: translateY(-4px);\n    }\n    .boxes.ok input { border-color: #4ade80; color: #4ade80; }\n    .boxes.bad input { border-color: #ff6b6b; color: #ff6b6b; }\n    .boxes.bad { animation: shake .4s; }\n    @keyframes shake {\n      25% { transform: translateX(-10px); }\n      75% { transform: translateX(10px); }\n    }\n    #msg { height: 26px; font-weight: 600; color: #4ade80; }\n    #msg.bad { color: #ff6b6b; }\n  </style>\n</head>\n<body>\n  <div class=\"card\">\n    <h1>Enter code</h1>\n    <p>We sent a 4-digit code to your phone</p>\n    <div class=\"boxes\" id=\"boxes\">\n      <input maxlength=\"1\" inputmode=\"numeric\" autofocus>\n      <input maxlength=\"1\" inputmode=\"numeric\">\n      <input maxlength=\"1\" inputmode=\"numeric\">\n      <input maxlength=\"1\" inputmode=\"numeric\">\n    </div>\n    <p id=\"msg\"></p>\n  </div>\n\n  <script>\n    const wrap = document.getElementById(\"boxes\");\n    const boxes = [...wrap.querySelectorAll(\"input\")];\n    const msg = document.getElementById(\"msg\");\n\n    boxes.forEach((box, i) => {\n      // jump to the next box when a digit is typed\n      box.oninput = () => {\n        box.value = box.value.replace(/\\D/g, \"\");\n        if (box.value) boxes[i + 1]?.focus();\n        check();\n      };\n      // backspace on an empty box goes back\n      box.onkeydown = (e) => {\n        if (e.key === \"Backspace\" && !box.value) boxes[i - 1]?.focus();\n      };\n    });\n\n    function check() {\n      const code = boxes.map((b) => b.value).join(\"\");\n      wrap.className = \"boxes\";\n      msg.className = \"\";\n      msg.textContent = \"\";\n      if (code.length < 4) return;\n      if (code === \"1234\") {          // demo code\n        wrap.classList.add(\"ok\");\n        msg.textContent = \"Verified ✓\";\n      } else {\n        wrap.classList.add(\"bad\");\n        msg.classList.add(\"bad\");\n        msg.textContent = \"Wrong code, try again\";\n      }\n    }\n  </script>\n</body>\n</html>\n", "dl": "demos/otp.html"}, {"id": "navbar", "emoji": "🫧", "title": "Sticky Glass Navbar", "desc": "Glass blur, underline hover, shrinks on scroll.", "tags": ["HTML", "CSS", "JS"], "video": "https://youtube.com/shorts/vCM7XuOBDpc", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Sticky Glass Navbar</title>\n  <style>\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    html { scroll-behavior: smooth; }\n    body {\n      font-family: \"Poppins\", system-ui, sans-serif;\n      font-size: 18px;\n      color: #e8eaf6;\n      background: #0b0d17;\n    }\n    .nav {\n      position: sticky;\n      top: 0;\n      z-index: 10;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 20px 6%;\n      background: rgba(11, 13, 23, .55);\n      backdrop-filter: blur(14px);\n      border-bottom: 1px solid rgba(255, 255, 255, .08);\n      transition: padding .3s;\n    }\n    .nav.small { padding: 10px 6%; }\n    .logo { font-weight: 800; font-size: 24px; color: #ff78be; }\n    .links a {\n      position: relative;\n      margin-left: 30px;\n      color: #c9cde8;\n      text-decoration: none;\n    }\n    .links a::after {\n      content: \"\";\n      position: absolute;\n      left: 0;\n      bottom: -6px;\n      width: 0;\n      height: 3px;\n      border-radius: 3px;\n      background: linear-gradient(90deg, #ff78be, #78dcff);\n      transition: width .3s;\n    }\n    .links a:hover::after { width: 100%; }\n    section { min-height: 90vh; display: grid; place-items: center; font-size: 54px; font-weight: 800; }\n    .s1 { background: linear-gradient(135deg, #6d28d9, #ff78be); }\n    .s2 { background: linear-gradient(135deg, #0ea5e9, #6366f1); }\n    .s3 { background: linear-gradient(135deg, #f97316, #ff78be); }\n    .s4 { background: linear-gradient(135deg, #10b981, #0ea5e9); }\n  </style>\n</head>\n<body>\n  <header class=\"nav\" id=\"nav\">\n    <span class=\"logo\">alex.dev</span>\n    <nav class=\"links\">\n      <a href=\"#a\">Home</a>\n      <a href=\"#b\">Work</a>\n      <a href=\"#c\">About</a>\n      <a href=\"#d\">Contact</a>\n    </nav>\n  </header>\n\n  <section class=\"s1\" id=\"a\">Home</section>\n  <section class=\"s2\" id=\"b\">Work</section>\n  <section class=\"s3\" id=\"c\">About</section>\n  <section class=\"s4\" id=\"d\">Contact</section>\n\n  <script>\n    const nav = document.getElementById(\"nav\");\n    // shrink the navbar a little after scrolling\n    window.onscroll = () => {\n      nav.classList.toggle(\"small\", window.scrollY > 60);\n    };\n  </script>\n</body>\n</html>\n", "dl": "demos/navbar.html"}, {"id": "toggle", "emoji": "🌙", "title": "Dark / Light Toggle", "desc": "A smooth switch that changes the whole mood.", "tags": ["HTML", "CSS", "JS"], "video": "https://youtube.com/shorts/4Xy79_qWkIw", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Dark Light Toggle</title>\n  <style>\n    * { margin: 0; padding: 0; box-sizing: border-box; }\n    body {\n      min-height: 100vh;\n      display: grid;\n      place-items: center;\n      font-family: \"Poppins\", system-ui, sans-serif;\n      font-size: 18px;\n      color: #e8eaf6;\n      background: radial-gradient(circle at 50% 0%, #2d1757, #0b0d17 65%);\n      transition: background .5s, color .5s;\n    }\n    body.light {\n      color: #1b1e33;\n      background: radial-gradient(circle at 50% 0%, #ffe3f1, #f4f7ff 65%);\n    }\n    .box { text-align: center; }\n    h1 { font-size: 46px; margin-bottom: 8px; }\n    p { color: #8b90b0; margin-bottom: 44px; transition: color .5s; }\n    body.light p { color: #5d627e; }\n    .switch {\n      position: relative;\n      width: 150px;\n      height: 76px;\n      border: none;\n      border-radius: 76px;\n      background: #1b2140;\n      box-shadow: inset 0 4px 14px rgba(0, 0, 0, .5);\n      cursor: pointer;\n      transition: background .4s;\n    }\n    .switch.on { background: #9bdcff; box-shadow: inset 0 4px 14px rgba(0, 0, 0, .15); }\n    .knob {\n      position: absolute;\n      top: 8px;\n      left: 8px;\n      width: 60px;\n      height: 60px;\n      display: grid;\n      place-items: center;\n      font-size: 30px;\n      border-radius: 50%;\n      background: #0b0d17;\n      transition: transform .4s cubic-bezier(.6, -.3, .3, 1.3), background .4s;\n    }\n    .switch.on .knob {\n      transform: translateX(74px);\n      background: #fff;\n    }\n  </style>\n</head>\n<body>\n  <div class=\"box\">\n    <h1 id=\"title\">Good night</h1>\n    <p>Tap the switch to change the mood</p>\n    <button class=\"switch\" id=\"sw\"><span class=\"knob\" id=\"knob\">🌙</span></button>\n  </div>\n\n  <script>\n    const sw = document.getElementById(\"sw\");\n    const title = document.getElementById(\"title\");\n    const knob = document.getElementById(\"knob\");\n\n    sw.onclick = () => {\n      sw.classList.toggle(\"on\");\n      document.body.classList.toggle(\"light\");\n      const light = sw.classList.contains(\"on\");\n      title.textContent = light ? \"Good morning\" : \"Good night\";\n      knob.textContent = light ? \"☀️\" : \"🌙\";\n    };\n  </script>\n</body>\n</html>\n", "dl": "demos/toggle.html"}, {"id": "floating_cards", "emoji": "☁️", "title": "Floating Cards", "desc": "One hover rule lifts the cards up with a soft glow.", "tags": ["HTML", "CSS"], "video": "https://youtube.com/shorts/JR6FBuWOG6Y", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Floating Cards</title>\n<style>\n* { margin: 0; padding: 0; box-sizing: border-box; }\nbody {\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  font-family: \"Poppins\", system-ui, sans-serif;\n  color: #e8eaf6;\n  background: radial-gradient(circle at 50% 0%, #2d1757, #0b0d17 65%);\n}\n.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; width: 860px; }\n.card {\n  background: rgba(255,255,255,.07);\n  border-radius: 18px;\n  padding: 20px;\n  transition: transform .3s, box-shadow .3s;\n}\n.card:hover {\n  transform: translateY(-8px);\n  box-shadow: 0 12px 30px #ff78be40;\n}\n.thumb { height: 130px; border-radius: 12px; display: grid; place-items: center; font-size: 48px; margin-bottom: 14px; background: linear-gradient(135deg, #7c5cff, #ff78be); }\n.card:nth-child(2) .thumb { background: linear-gradient(135deg, #22d3ee, #6366f1); }\n.card:nth-child(3) .thumb { background: linear-gradient(135deg, #fb923c, #ff78be); }\nh3 { margin-bottom: 6px; }\np { color: #a9a6d4; font-size: 15px; }\n</style>\n</head>\n<body>\n<div class=\"grid\">\n  <div class=\"card\"><div class=\"thumb\">🎨</div><h3>Project one</h3><p>Hover me!</p></div>\n  <div class=\"card\"><div class=\"thumb\">🚀</div><h3>Project two</h3><p>I float up too.</p></div>\n  <div class=\"card\"><div class=\"thumb\">🌸</div><h3>Project three</h3><p>Soft pink glow.</p></div>\n</div>\n</body>\n</html>\n", "dl": "demos/floating_cards.html"}, {"id": "typing", "emoji": "✨", "title": "Typing Effect", "desc": "Text that types and deletes itself.", "tags": ["HTML", "JS"], "video": "", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Typing Effect</title>\n<style>\n* { margin: 0; padding: 0; box-sizing: border-box; }\nbody {\n  min-height: 100vh;\n  font-family: \"Poppins\", system-ui, sans-serif;\n  color: #e8eaf6;\n  background: radial-gradient(circle at 50% 0%, #2d1757, #0b0d17 65%);\n  display: grid; place-items: center;\n}\n\n.box { text-align: center; }\n.hi { color: #8b90b0; font-size: 36px; margin-bottom: 10px; }\nh1 { font-size: 100px; }\n#t { color: #ff78be; }\n.cur { display: inline-block; width: 7px; height: 96px; margin-left: 8px; vertical-align: -12px; background: #78dcff; animation: blink .8s steps(1) infinite; }\n@keyframes blink { 50% { opacity: 0; } }\n\n</style>\n</head>\n<body>\n<div class=\"box\"><p class=\"hi\">Hi, I'm Rhea</p><h1>I'm a <span id=\"t\"></span><i class=\"cur\"></i></h1></div>\n<script>\nconst t = document.getElementById(\"t\");\nconst w = [\"Coder\", \"Designer\", \"Creator\"];\nlet i = 0, j = 0, del = false;\nsetInterval(() => {\n  const s = w[i];\n  j += del ? -1 : 1;\n  t.textContent = s.slice(0, j);\n  if (j == s.length) del = true;\n  if (j == 0) { del = false; i = (i + 1) % w.length; }\n}, 130);\n</script>\n</body>\n</html>\n", "dl": "demos/typing.html"}, {"id": "progress", "emoji": "🍡", "title": "Scroll Progress Bar", "desc": "A bar that grows as you scroll.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Scroll Progress</title>\n<style>\n* { margin: 0; padding: 0; box-sizing: border-box; }\nbody {\n  min-height: 100vh;\n  font-family: \"Poppins\", system-ui, sans-serif;\n  color: #e8eaf6;\n  background: radial-gradient(circle at 50% 0%, #2d1757, #0b0d17 65%);\n  \n}\n\n#bar { position: fixed; top: 0; left: 0; height: 8px; width: 0; z-index: 9; background: linear-gradient(90deg, #ff78be, #78dcff); box-shadow: 0 0 14px #ff78be; }\n.top { position: fixed; top: 8px; left: 0; right: 0; padding: 18px 40px; font-weight: 600; background: rgba(11,13,23,.7); backdrop-filter: blur(10px); }\nmain { padding: 120px 60px 160px; max-width: 900px; margin: auto; }\nh2 { font-size: 40px; margin: 70px 0 16px; color: #78dcff; }\np { font-size: 21px; line-height: 1.7; color: #b9bddb; }\n\n</style>\n</head>\n<body>\n<div id=\"bar\"></div><div class=\"top\">Reading progress</div><main><h2>Why it works</h2><p>Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. </p><h2>The magic line</h2><p>Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. </p><h2>Make it yours</h2><p>Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. </p><h2>Smooth and simple</h2><p>Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. </p><h2>Keep scrolling</h2><p>Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. </p><h2>Almost there</h2><p>Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. </p><h2>The end</h2><p>Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. Scroll to see the bar grow. Every line you read fills it a little more. </p></main>\n<script>\nconst bar = document.getElementById(\"bar\");\nwindow.onscroll = () => {\n  const h = document.body.scrollHeight - innerHeight;\n  bar.style.width = scrollY / h * 100 + \"%\";\n};\n</script>\n</body>\n</html>\n", "dl": "demos/progress.html"}, {"id": "accordion", "emoji": "🍰", "title": "FAQ Accordion", "desc": "Answers that slide open smoothly.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>FAQ Accordion</title>\n<style>\n* { margin: 0; padding: 0; box-sizing: border-box; }\nbody {\n  min-height: 100vh;\n  font-family: \"Poppins\", system-ui, sans-serif;\n  color: #e8eaf6;\n  background: radial-gradient(circle at 50% 0%, #2d1757, #0b0d17 65%);\n  display: grid; place-items: center;\n}\n\n.faq { width: 760px; zoom: 1.12; }\nh1 { text-align: center; font-size: 46px; margin-bottom: 30px; }\n.item { margin-bottom: 16px; border-radius: 18px; background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.14); overflow: hidden; }\n.q { width: 100%; display: flex; justify-content: space-between; padding: 22px 26px; font: 600 22px Poppins, sans-serif; color: #fff; background: none; border: 0; cursor: pointer; }\n.q span { color: #ff78be; transition: transform .4s; }\n.item.open .q span { transform: rotate(45deg); }\n.answer { max-height: 0; overflow: hidden; transition: max-height .4s; }\n.answer p { padding: 0 26px 24px; font-size: 19px; line-height: 1.6; color: #b9bddb; }\n.item.open .answer { max-height: 100px; }\n\n</style>\n</head>\n<body>\n<div class=\"faq\"><h1>FAQ</h1>\n<div class=\"item\"><button class=\"q\">Is it free? <span>+</span></button><div class=\"answer\"><p>Yes! Free code, free to use, free to change.</p></div></div>\n<div class=\"item\"><button class=\"q\">Do I need a framework? <span>+</span></button><div class=\"answer\"><p>Nope. Just HTML, CSS and a tiny bit of JavaScript.</p></div></div>\n<div class=\"item\"><button class=\"q\">Works on mobile? <span>+</span></button><div class=\"answer\"><p>Yes, it fits any screen size.</p></div></div></div>\n<script>\ndocument.querySelectorAll(\".q\").forEach(q => {\n  q.onclick = () => {\n    q.parentElement.classList.toggle(\"open\");\n  };\n});\n</script>\n</body>\n</html>\n", "dl": "demos/accordion.html"}, {"id": "copy", "emoji": "💌", "title": "Copy Button", "desc": "Copy to clipboard with a Copied! message.", "tags": ["HTML", "JS"], "video": "", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Copy Button</title>\n<style>\n* { margin: 0; padding: 0; box-sizing: border-box; }\nbody {\n  min-height: 100vh;\n  font-family: \"Poppins\", system-ui, sans-serif;\n  color: #e8eaf6;\n  background: radial-gradient(circle at 50% 0%, #2d1757, #0b0d17 65%);\n  display: grid; place-items: center;\n}\n\n.box { zoom: 1.12; width: 780px; border-radius: 20px; overflow: hidden; background: #14122b; border: 1px solid #3a3566; }\n.bar { display: flex; justify-content: space-between; align-items: center; padding: 14px 20px; background: #1d1a3a; color: #8b88b8; font-size: 18px; }\n#btn { padding: 8px 20px; border: 0; border-radius: 10px; font: 600 16px Poppins, sans-serif; cursor: pointer; color: #1a1030; background: linear-gradient(90deg, #ff78be, #78dcff); transition: transform .2s, background .3s; }\n#btn:hover { transform: scale(1.06); }\n#btn.done { background: #7af0a8; }\npre { padding: 26px 24px; font: 24px/1.6 \"DejaVu Sans Mono\", monospace; color: #cfd3ff; }\n.k { color: #ff78be; } .s { color: #7af0a8; }\n\n</style>\n</head>\n<body>\n<div class=\"box\"><div class=\"bar\"><span>index.html</span><button id=\"btn\">Copy</button></div><pre id=\"snippet\"><span class=\"k\">const</span> hello = <span class=\"s\">\"Hi!\"</span>;\nconsole.log(hello);</pre></div>\n<script>\nconst btn = document.getElementById(\"btn\");\nbtn.onclick = () => {\n  navigator.clipboard.writeText(snippet.innerText).catch(() => {});\n  btn.textContent = \"Copied!\";\n  btn.classList.add(\"done\");\n  setTimeout(() => {\n    btn.textContent = \"Copy\";\n    btn.classList.remove(\"done\");\n  }, 1500);\n};\n</script>\n</body>\n</html>\n", "dl": "demos/copy.html"}]}, {"title": "Portfolio Website", "emoji": "🎀", "desc": "Long video: build a full portfolio from an empty folder. Navbar, typing hero, projects grid, dark mode, contact form.", "video": "", "short": "", "zip": "downloads/portfolio_website_code.zip", "items": [{"title": "Portfolio Website", "emoji": "🎀", "desc": "3 files: index.html, style.css, script.js.", "tags": ["HTML", "CSS", "JS"], "img": "img/portfolio.jpg", "zip": "downloads/portfolio_website_code.zip", "video": ""}]}, {"title": "Login & Sign Up Page", "emoji": "🧸", "desc": "Long video: glass card, floating labels, validation, sign up mode and a strength bar.", "video": "", "short": "https://youtube.com/shorts/CYlmh0Jl6sY", "zip": "downloads/login_signup_code.zip", "items": [{"title": "Login & Sign Up Page", "emoji": "🧸", "desc": "3 files: index.html, style.css, script.js.", "tags": ["HTML", "CSS", "JS"], "img": "img/login.jpg", "zip": "downloads/login_signup_code.zip", "video": ""}]}, {"title": "10 Adorable CSS Buttons", "emoji": "💗", "desc": "Long video: 10 satisfying buttons with HTML and CSS. Each page has two buttons.", "video": "", "short": "https://youtube.com/shorts/DoebFQD4pTw", "zip": "downloads/css_buttons_code.zip", "items": [{"id": "btn_press_shine", "emoji": "🍬", "title": "Press & Shine", "desc": "Squishy press button and a shine sweep.", "tags": ["HTML", "CSS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Press & Shine</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n#stage{--main:#ff8fb1;--dk:color-mix(in srgb,var(--main) 72%,#5a2a40)}\n.note{margin:0;font-size:15px;font-weight:700;opacity:.7}\n.cell{display:flex;flex-direction:column;align-items:center;gap:14px}\n.btn{font:inherit;font-weight:700;font-size:26px;color:#fff;background:var(--main);border:none;border-radius:24px;padding:0 48px;height:76px;min-width:330px;cursor:pointer;position:relative}\n#stage{gap:44px}\n.b3d{box-shadow:0 10px 0 var(--dk);transition:transform .1s,box-shadow .1s}\n.b3d:hover{transform:translateY(2px);box-shadow:0 8px 0 var(--dk)}\n.b3d:active{transform:translateY(10px);box-shadow:0 0 0 var(--dk)}\n.shine{overflow:hidden;box-shadow:0 8px 18px rgba(255,143,177,.4)}\n.shine::after{content:\"\";position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(120deg,transparent,rgba(255,255,255,.85),transparent);transform:skewX(-20deg)}\n.shine:hover::after{left:130%;transition:left .6s}\n</style></head><body><div id=\"stage\"><div class=\"cell\"><button class=\"btn b3d\" id=\"lab\">press me</button><p class=\"note\">1 · squishy press</p></div>\n<div class=\"cell\"><button class=\"btn shine\">shine</button><p class=\"note\">2 · shine sweep</p></div></div><script>const COLOR=\"#c9a7ff\", LABEL=\"Tap me gently\";\ndocument.getElementById(\"stage\").style.setProperty(\"--main\",COLOR);\ndocument.getElementById(\"lab\").textContent=LABEL;\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/btn_press_shine.html"}, {"id": "btn_slide_arrow", "emoji": "💌", "title": "Slide & Arrow", "desc": "A slide fill button and an arrow that moves.", "tags": ["HTML", "CSS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Slide & Arrow</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n#stage{--main:#ff8fb1;--dk:color-mix(in srgb,var(--main) 72%,#5a2a40)}\n.note{margin:0;font-size:15px;font-weight:700;opacity:.7}\n.cell{display:flex;flex-direction:column;align-items:center;gap:14px}\n.btn{font:inherit;font-weight:700;font-size:26px;color:#fff;background:var(--main);border:none;border-radius:24px;padding:0 48px;height:76px;min-width:330px;cursor:pointer;position:relative}\n#stage{gap:44px}\n.fill{background:#fff;color:var(--main);box-shadow:0 0 0 3px var(--main) inset;overflow:hidden;z-index:0;transition:color .35s}\n.fill::before{content:\"\";position:absolute;inset:0;background:var(--main);transform:translateX(-101%);transition:transform .35s;z-index:-1}\n.fill:hover{color:#fff}.fill:hover::before{transform:none}\n.arrow{box-shadow:0 8px 18px rgba(255,143,177,.4)}\n.arrow span{display:inline-block;transition:transform .3s}\n.arrow:hover span{transform:translateX(12px)}\n</style></head><body><div id=\"stage\"><div class=\"cell\"><button class=\"btn fill\" id=\"lab\">hover me</button><p class=\"note\">3 · slide fill</p></div>\n<div class=\"cell\"><button class=\"btn arrow\">send <span>→</span></button><p class=\"note\">4 · arrow push</p></div></div><script>const COLOR=\"#ffa98f\", LABEL=\"Send love\";\ndocument.getElementById(\"stage\").style.setProperty(\"--main\",COLOR);\ndocument.getElementById(\"lab\").textContent=LABEL;\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/btn_slide_arrow.html"}, {"id": "btn_jelly_glow", "emoji": "🫧", "title": "Jelly & Glow", "desc": "A wobbly jelly button and a glowing one.", "tags": ["HTML", "CSS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Jelly & Glow</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n#stage{--main:#ff8fb1;--dk:color-mix(in srgb,var(--main) 72%,#5a2a40)}\n.note{margin:0;font-size:15px;font-weight:700;opacity:.7}\n.cell{display:flex;flex-direction:column;align-items:center;gap:14px}\n.btn{font:inherit;font-weight:700;font-size:26px;color:#fff;background:var(--main);border:none;border-radius:24px;padding:0 48px;height:76px;min-width:330px;cursor:pointer;position:relative}\n#stage{gap:44px}\n.jelly{box-shadow:0 8px 18px rgba(255,143,177,.4)}\n.jelly:hover{animation:jelly .6s}\n@keyframes jelly{25%{transform:scale(1.2,.8)}50%{transform:scale(.85,1.15)}75%{transform:scale(1.08,.92)}100%{transform:scale(1)}}\n.glow{background:linear-gradient(90deg,var(--main),#ffcfb3,var(--main));background-size:200% 100%;transition:background-position .6s,box-shadow .3s}\n.glow:hover{background-position:100% 0;box-shadow:0 0 30px var(--main)}\n</style></head><body><div id=\"stage\"><div class=\"cell\"><button class=\"btn jelly\" id=\"lab\">bounce</button><p class=\"note\">5 · jelly bounce</p></div>\n<div class=\"cell\"><button class=\"btn glow\">glow</button><p class=\"note\">6 · soft glow</p></div></div><script>const COLOR=\"#8fc9ff\", LABEL=\"Boing!\";\ndocument.getElementById(\"stage\").style.setProperty(\"--main\",COLOR);\ndocument.getElementById(\"lab\").textContent=LABEL;\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/btn_jelly_glow.html"}, {"id": "btn_ripple_heart", "emoji": "💓", "title": "Ripple & Heart", "desc": "A ripple click effect and a heart like button.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Ripple & Heart</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n#stage{--main:#ff8fb1;--dk:color-mix(in srgb,var(--main) 72%,#5a2a40)}\n.note{margin:0;font-size:15px;font-weight:700;opacity:.7}\n.cell{display:flex;flex-direction:column;align-items:center;gap:14px}\n.btn{font:inherit;font-weight:700;font-size:26px;color:#fff;background:var(--main);border:none;border-radius:24px;padding:0 48px;height:76px;min-width:330px;cursor:pointer;position:relative}\n#stage{gap:44px}\n.rip{overflow:hidden;box-shadow:0 8px 18px rgba(255,143,177,.4)}\n.rip .r{position:absolute;width:20px;height:20px;border-radius:50%;background:rgba(255,255,255,.65);transform:translate(-50%,-50%) scale(0);animation:rp .7s ease-out forwards;pointer-events:none}\n@keyframes rp{to{transform:translate(-50%,-50%) scale(16);opacity:0}}\n.like{background:#fff;color:var(--main);box-shadow:0 0 0 3px var(--main) inset;transition:background .25s,color .25s}\n.like.on{background:var(--main);color:#fff}\n.mini{position:absolute;left:50%;top:50%;color:var(--main);pointer-events:none;animation:fly 1.2s ease-out forwards}\n@keyframes fly{to{transform:translate(var(--dx),var(--dy)) rotate(var(--r));opacity:0}}\n</style></head><body><div id=\"stage\"><div class=\"cell\"><button class=\"btn rip\" id=\"lab\">click me</button><p class=\"note\">7 · ripple click</p></div>\n<div class=\"cell\"><button class=\"btn like\" id=\"like\">♡ like</button><p class=\"note\">8 · heart burst</p></div></div><script>const COLOR=\"#ff9fcf\", LABEL=\"Click me!\";\ndocument.getElementById(\"stage\").style.setProperty(\"--main\",COLOR);\ndocument.getElementById(\"lab\").textContent=LABEL;\nconst rip=document.querySelector(\".rip\");\nrip.onclick=e=>{\n  const r=document.createElement(\"span\");r.className=\"r\";\n  r.style.left=e.offsetX+\"px\";r.style.top=e.offsetY+\"px\";\n  rip.appendChild(r);setTimeout(()=>r.remove(),750);\n};\nconst like=document.getElementById(\"like\");\nlike.onclick=()=>{\n  const on=like.classList.toggle(\"on\");\n  like.textContent=on?\"♥ liked\":\"♡ like\";\n  if(!on)return;\n  for(let i=0;i<8;i++){\n    const m=document.createElement(\"div\");m.className=\"mini\";m.textContent=\"♥\";\n    const a=Math.random()*6.28,d=60+Math.random()*70;\n    m.style.setProperty(\"--dx\",Math.cos(a)*d+\"px\");m.style.setProperty(\"--dy\",Math.sin(a)*d+\"px\");\n    m.style.setProperty(\"--r\",(Math.random()*120-60)+\"deg\");m.style.fontSize=(14+Math.random()*16)+\"px\";\n    like.appendChild(m);setTimeout(()=>m.remove(),1300);\n  }\n};\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/btn_ripple_heart.html"}, {"id": "btn_switch_load", "emoji": "🌷", "title": "Switch & Loading", "desc": "A toggle switch and a loading button.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Switch & Load</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n#stage{--main:#ff8fb1;--dk:color-mix(in srgb,var(--main) 72%,#5a2a40)}\n.note{margin:0;font-size:15px;font-weight:700;opacity:.7}\n.cell{display:flex;flex-direction:column;align-items:center;gap:14px}\n.btn{font:inherit;font-weight:700;font-size:26px;color:#fff;background:var(--main);border:none;border-radius:24px;padding:0 48px;height:76px;min-width:330px;cursor:pointer;position:relative}\n#stage{gap:44px}\n.sw{display:flex;align-items:center;gap:16px;cursor:pointer;font-size:24px}\n.sw input{display:none}\n.sw span{width:80px;height:44px;border-radius:20px;background:#ffd6e3;position:relative;transition:background .3s}\n.sw span::after{content:\"\";position:absolute;top:4px;left:4px;width:36px;height:36px;border-radius:50%;background:#fff;box-shadow:0 2px 6px rgba(0,0,0,.2);transition:transform .3s cubic-bezier(.3,1.4,.5,1)}\n.sw input:checked+span{background:var(--main)}\n.sw input:checked+span::after{transform:translateX(36px)}\n.load{display:inline-flex;align-items:center;justify-content:center;box-shadow:0 8px 18px rgba(255,143,177,.4);transition:background .3s}\n.load.busy::after{content:\"\";width:30px;height:30px;border:4px solid #fff;border-top-color:transparent;border-radius:50%;animation:spin .7s linear infinite}\n.load.ok{background:#7fd8b5}\n@keyframes spin{to{transform:rotate(360deg)}}\n</style></head><body><div id=\"stage\"><div class=\"cell\"><label class=\"sw\"><input type=\"checkbox\" id=\"t\"><span></span><b>sleepy mode</b></label><p class=\"note\">9 · toggle switch</p></div>\n<div class=\"cell\"><button class=\"btn load\" id=\"lab\">send it</button><p class=\"note\">10 · loading button</p></div></div><script>const COLOR=\"#a78bfa\", LABEL=\"Send love\";\ndocument.getElementById(\"stage\").style.setProperty(\"--main\",COLOR);\ndocument.getElementById(\"lab\").textContent=LABEL;\nconst load=document.getElementById(\"lab\");\nload.onclick=()=>{\n  if(load.classList.contains(\"busy\")||load.classList.contains(\"ok\"))return;\n  load.classList.add(\"busy\");load.textContent=\"\";\n  setTimeout(()=>{\n    load.classList.remove(\"busy\");load.classList.add(\"ok\");load.textContent=\"done ✓\";\n    setTimeout(()=>{load.classList.remove(\"ok\");load.textContent=LABEL},1400);\n  },1400);\n};\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/btn_switch_load.html"}]}, {"title": "5 Useful Tools", "emoji": "🧰", "desc": "Long video: five useful tools with HTML, CSS and JavaScript.", "video": "", "short": "", "zip": "downloads/cute_useful_tools_code.zip", "items": [{"id": "tool_timer", "emoji": "⏰", "title": "Study Timer", "desc": "A round timer with start and reset.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Study Timer</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n.ring{position:relative;width:230px;height:230px}\n.ring svg{transform:rotate(-90deg)}\n.track,.arc{fill:none;stroke-width:16}\n.track{stroke:#ffd6e3}\n.arc{stroke:#ff7fa3;stroke-linecap:round;stroke-dasharray:628.3;stroke-dashoffset:0;transition:stroke-dashoffset 1s linear}\n.mid{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px}\n#label{font-size:22px}#time{font-size:48px;font-weight:700;letter-spacing:1px}\n.row{display:flex;gap:12px}\n</style></head><body><div id=\"stage\"><div class=\"ring\">\n <svg width=\"230\" height=\"230\" viewBox=\"0 0 230 230\"><circle class=\"track\" cx=\"115\" cy=\"115\" r=\"100\"/><circle id=\"arc\" class=\"arc\" cx=\"115\" cy=\"115\" r=\"100\"/></svg>\n <div class=\"mid\"><div id=\"label\" class=\"pacifico\">Study time</div><div id=\"time\">25:00</div></div>\n</div>\n<div class=\"row\"><button id=\"go\">start</button><button id=\"rst\" class=\"ghost\">reset</button></div></div><script>const LABEL=\"Maths time\", MINUTES=Number(\"1\");\ndocument.getElementById(\"label\").textContent=LABEL;\nconst arc=document.getElementById(\"arc\"),time=document.getElementById(\"time\"),go=document.getElementById(\"go\"),rst=document.getElementById(\"rst\");\nconst TOTAL=MINUTES*60;let left=TOTAL,timer=null;\nfunction draw(){\n  const m=Math.floor(left/60),s=Math.floor(left%60);\n  time.textContent=String(m).padStart(2,\"0\")+\":\"+String(s).padStart(2,\"0\");\n  arc.style.strokeDashoffset=628.3*(1-left/TOTAL);\n}\ngo.onclick=()=>{\n  if(timer){clearInterval(timer);timer=null;go.textContent=\"start\";return}\n  go.textContent=\"pause\";\n  timer=setInterval(()=>{\n    left=Math.max(0,left-1);draw();\n    if(left==0){clearInterval(timer);timer=null;go.textContent=\"start\";time.textContent=\"done!\"}\n  },1000);\n};\nrst.onclick=()=>{clearInterval(timer);timer=null;left=TOTAL;go.textContent=\"start\";draw()};\ndraw();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/tool_timer.html"}, {"id": "tool_password", "emoji": "🔐", "title": "Password Maker", "desc": "Pick a length and make a strong password.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Password Maker</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n.box{display:flex;align-items:center;gap:10px;background:#fff;border-radius:18px;padding:10px 12px 10px 16px;width:380px;box-shadow:0 8px 20px rgba(255,143,177,.3),0 0 0 3px #ffd6e3 inset}\n#pw{flex:1;font-family:monospace;font-size:20px;font-weight:700;word-break:break-all;text-align:left;letter-spacing:1px}\n.box button{padding:7px 14px;font-size:14px}\n.srow{display:flex;align-items:center;gap:12px;font-weight:700;font-size:15px}\ninput[type=range]{accent-color:#ff7fa3;width:170px}\n.bar{width:300px;height:12px;border-radius:8px;background:#ffd6e3;overflow:hidden}\n.bar i{display:block;height:100%;width:30%;border-radius:8px;background:linear-gradient(90deg,#ffb3c9,#ff7fa3);transition:width .5s}\n</style></head><body><div id=\"stage\"><h2 class=\"pacifico\">Password Maker</h2>\n<div class=\"box\"><span id=\"pw\">••••••••</span><button id=\"copy\" class=\"ghost\">copy</button></div>\n<div class=\"srow\"><label>length <b id=\"len\">12</b></label><input id=\"slider\" type=\"range\" min=\"8\" max=\"24\" value=\"12\"></div>\n<div class=\"bar\"><i id=\"fill\"></i></div><p id=\"note\" class=\"note\">strength</p>\n<button id=\"make\">make password</button></div><script>const SYMBOLS=\"!@#$%\", LENGTH=Number(\"16\");\nconst LETTERS=\"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\";\nconst pw=document.getElementById(\"pw\"),slider=document.getElementById(\"slider\"),len=document.getElementById(\"len\");\nconst fill=document.getElementById(\"fill\"),note=document.getElementById(\"note\");\nslider.value=LENGTH;len.textContent=LENGTH;\nfunction make(){\n  const chars=LETTERS+SYMBOLS,n=Number(slider.value),r=new Uint32Array(n);\n  crypto.getRandomValues(r);\n  pw.textContent=Array.from(r,v=>chars[v%chars.length]).join(\"\");\n  fill.style.width=((n-4)/20*100)+\"%\";\n  note.textContent=n<12?\"strength: okay\":n<16?\"strength: strong\":\"strength: super strong\";\n}\nslider.oninput=()=>{len.textContent=slider.value;make()};\ndocument.getElementById(\"make\").onclick=make;\ndocument.getElementById(\"copy\").onclick=e=>{\n  if(navigator.clipboard)navigator.clipboard.writeText(pw.textContent).catch(()=>{});\n  e.target.textContent=\"copied ♥\";setTimeout(()=>e.target.textContent=\"copy\",1200);\n};\nmake();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/tool_password.html"}, {"id": "tool_palette", "emoji": "🎨", "title": "Palette Maker", "desc": "Make color palettes and tap a color to copy it.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Palette Maker</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n.pal{display:flex;gap:8px;width:420px;height:210px}\n.sw{flex:1;border-radius:18px;display:flex;align-items:flex-end;justify-content:center;padding-bottom:12px;font-size:12px;font-weight:700;cursor:pointer;color:#7a3b52;transition:background .5s,transform .2s;box-shadow:0 8px 18px rgba(255,143,177,.25),0 0 0 4px #fff inset}\n.sw:hover{transform:translateY(-6px)}\n</style></head><body><div id=\"stage\"><h2 class=\"pacifico\">Palette Maker</h2>\n<div class=\"pal\" id=\"pal\"></div>\n<button id=\"new\">new colors</button>\n<p id=\"note\" class=\"note\">tap a color to copy it</p></div><script>const HUE_START=Number(\"320\"), HUE_RANGE=Number(\"70\");\nconst pal=document.getElementById(\"pal\"),note=document.getElementById(\"note\");\nfunction hex(h,s,l){\n  s/=100;l/=100;const a=s*Math.min(l,1-l);\n  const f=n=>{const k=(n+h/30)%12;return Math.round(255*(l-a*Math.max(-1,Math.min(k-3,9-k,1)))).toString(16).padStart(2,\"0\")};\n  return \"#\"+f(0)+f(8)+f(4);\n}\nfunction newColors(){\n  pal.innerHTML=\"\";\n  for(let i=0;i<5;i++){\n    const h=(HUE_START+HUE_RANGE*i/4+Math.random()*10)%360;\n    const c=hex(h,65+Math.random()*20,82+Math.random()*8);\n    const d=document.createElement(\"div\");d.className=\"sw\";d.style.background=c;d.textContent=c;\n    d.onclick=()=>{if(navigator.clipboard)navigator.clipboard.writeText(c).catch(()=>{});note.textContent=\"copied \"+c+\" ♥\"};\n    pal.appendChild(d);\n  }\n}\ndocument.getElementById(\"new\").onclick=newColors;\nnewColors();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/tool_palette.html"}, {"id": "tool_countdown", "emoji": "🎂", "title": "Countdown", "desc": "Days, hours, minutes and seconds to a date. Change the date in the code!", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Countdown</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n.top{margin:0;font-size:32px}\n.big{display:flex;align-items:baseline;gap:10px;color:#e0668f}\n.big b{font-size:110px;line-height:1;text-shadow:0 8px 20px rgba(255,143,177,.45)}\n.big span{font-size:26px;font-weight:700}\n.small{display:flex;gap:14px}\n.small div{background:#fff;border-radius:18px;padding:10px 0;width:92px;font-size:13px;font-weight:700;box-shadow:0 8px 18px rgba(255,143,177,.25),0 0 0 3px #ffd6e3 inset;display:flex;flex-direction:column;gap:2px}\n.small b{font-size:34px;color:#7a3b52;line-height:1.1}\n#s{display:inline-block;animation:tick 1s ease-in-out infinite}\n@keyframes tick{0%{transform:scale(1)}15%{transform:scale(1.25);color:#e0668f}40%,100%{transform:scale(1)}}\n</style></head><body><div id=\"stage\"><p id=\"ev\" class=\"pacifico top\">The big day</p>\n<div class=\"big\"><b id=\"d\">0</b><span>days</span></div>\n<div class=\"small\"><div><b id=\"h\">0</b>hours</div><div><b id=\"m\">0</b>min</div><div><b id=\"s\">0</b>sec</div></div>\n<p id=\"foot\" class=\"note\">until something wonderful ♥</p></div><script>const EVENT=\"Birthday Month\", DATE=\"2027-03-01\";\ndocument.getElementById(\"ev\").textContent=EVENT;\nconst target=new Date(DATE).getTime();\nconst $=id=>document.getElementById(id);\nfunction tick(){\n  const diff=Math.max(0,target-Date.now());\n  $(\"d\").textContent=Math.floor(diff/864e5);\n  $(\"h\").textContent=Math.floor(diff/36e5)%24;\n  $(\"m\").textContent=Math.floor(diff/6e4)%60;\n  $(\"s\").textContent=Math.floor(diff/1000)%60;\n  if(diff==0)$(\"foot\").textContent=\"It's today! ♥\";\n}\ntick();setInterval(tick,1000);\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/tool_countdown.html"}, {"id": "tool_todo", "emoji": "📝", "title": "To-Do List", "desc": "Add, tick and delete tasks.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>To-Do List</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n.prog{width:340px;height:12px;border-radius:8px;background:#ffd6e3;overflow:hidden}\n.prog i{display:block;height:100%;width:0;border-radius:8px;background:linear-gradient(90deg,#ffb3c9,#ff7fa3);transition:width .5s}\nul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px;width:340px}\nli{display:flex;align-items:center;gap:12px;background:#fff;border-radius:16px;padding:9px 14px;font-weight:700;font-size:16px;text-align:left;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.22),0 0 0 2px #ffd6e3 inset;transition:transform .2s}\nli .h{color:#ffb3c9;font-size:22px;line-height:1}\nli.done{color:#e0668f;text-decoration:line-through;opacity:.8}li.done .h{color:#ff7fa3}\n.add{display:flex;gap:8px}\ninput{font:inherit;font-weight:500;width:230px;border:none;border-radius:20px;padding:9px 16px;background:#fff;color:#7a3b52;box-shadow:0 0 0 3px #ffd6e3 inset;outline:none}\n.add button{padding:9px 18px}\n</style></head><body><div id=\"stage\"><h2 id=\"title\" class=\"pacifico\">My To-Do</h2>\n<div class=\"prog\"><i id=\"bar\"></i></div><p id=\"count\" class=\"note\">0 / 0 done</p>\n<ul id=\"list\"></ul>\n<div class=\"add\"><input id=\"inp\" placeholder=\"add a task...\"><button id=\"addb\">add</button></div></div><script>const TITLE=\"Rhea's Day\", START=\"Drink water,Study one hour,Call mom\".split(\",\");\ndocument.getElementById(\"title\").textContent=TITLE;\nconst tasks=START.map(t=>({text:t.trim(),done:false}));\nconst list=document.getElementById(\"list\"),bar=document.getElementById(\"bar\"),count=document.getElementById(\"count\"),inp=document.getElementById(\"inp\");\nfunction draw(){\n  list.innerHTML=\"\";\n  tasks.forEach(t=>{\n    const li=document.createElement(\"li\");if(t.done)li.className=\"done\";\n    li.innerHTML='<span class=\"h\">'+(t.done?\"♥\":\"♡\")+\"</span>\"+t.text;\n    li.onclick=()=>{t.done=!t.done;draw()};list.appendChild(li);\n  });\n  const d=tasks.filter(t=>t.done).length;\n  bar.style.width=(tasks.length?d/tasks.length*100:0)+\"%\";\n  count.textContent=d==tasks.length&&d>0?\"all done! so proud of you ♥\":d+\" / \"+tasks.length+\" done\";\n}\nfunction add(){if(!inp.value.trim())return;tasks.push({text:inp.value.trim(),done:false});inp.value=\"\";draw()}\ndocument.getElementById(\"addb\").onclick=add;\ninp.onkeydown=e=>{if(e.key==\"Enter\")add()};\ndraw();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/tool_todo.html"}]}, {"title": "5 Cute Gift Cards", "emoji": "🎁", "desc": "Long video: five digital gift cards made with code.", "video": "", "short": "", "zip": "downloads/cute_cards_code.zip", "items": [{"id": "card_flip", "emoji": "🧸", "title": "Flip Card", "desc": "A card that flips over to show a message.", "tags": ["HTML", "CSS", "JS"], "video": "https://youtube.com/shorts/2gPvguimdAA", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Flip Card</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.scene{perspective:1200px;cursor:pointer}\n.card{width:250px;height:350px;position:relative;transition:transform .9s cubic-bezier(.3,1.3,.5,1);transform-style:preserve-3d;animation:bob 3.5s ease-in-out infinite}\n.card.open{transform:rotateY(180deg);animation:none}\n@keyframes bob{50%{transform:translateY(-6px) rotate(-1deg)}}\n.face{position:absolute;inset:0;border-radius:26px;backface-visibility:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:22px;box-shadow:0 16px 34px rgba(255,143,177,.35),0 0 0 7px #fff inset}\n.front{background:linear-gradient(160deg,#ffd6e3,#ffe9d9)}\n.back{background:linear-gradient(160deg,#fffaf5,#ffe3ec);transform:rotateY(180deg);font-size:17px;line-height:1.5;font-weight:500}\nh1{margin:0;font-size:26px}.sub{margin:0;font-size:13px;font-weight:700;opacity:.8}.back span{font-size:20px}\n</style></head><body><div id=\"stage\"><div class=\"scene\" id=\"scene\"><div class=\"card\" id=\"card\">\n <div class=\"face front\"><svg class=\"bear\" width=\"130\" height=\"130\" viewBox=\"0 0 200 200\"><circle cx=\"55\" cy=\"45\" r=\"26\" fill=\"#f3b58f\"/><circle cx=\"55\" cy=\"45\" r=\"14\" fill=\"#ffd9c7\"/><circle cx=\"145\" cy=\"45\" r=\"26\" fill=\"#f3b58f\"/><circle cx=\"145\" cy=\"45\" r=\"14\" fill=\"#ffd9c7\"/><circle cx=\"100\" cy=\"100\" r=\"64\" fill=\"#f7c7a3\"/><ellipse cx=\"100\" cy=\"122\" rx=\"30\" ry=\"23\" fill=\"#fff0e4\"/><ellipse cx=\"100\" cy=\"112\" rx=\"9\" ry=\"6.5\" fill=\"#7a3b52\"/><path d=\"M100 118v8M100 126q-8 8-15 2M100 126q8 8 15 2\" stroke=\"#7a3b52\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"76\" cy=\"92\" r=\"7\" fill=\"#7a3b52\"/><circle cx=\"124\" cy=\"92\" r=\"7\" fill=\"#7a3b52\"/><circle cx=\"78\" cy=\"89\" r=\"2.4\" fill=\"#fff\"/><circle cx=\"126\" cy=\"89\" r=\"2.4\" fill=\"#fff\"/><ellipse cx=\"58\" cy=\"112\" rx=\"11\" ry=\"7\" fill=\"#ff9fb8\" opacity=\".7\"/><ellipse cx=\"142\" cy=\"112\" rx=\"11\" ry=\"7\" fill=\"#ff9fb8\" opacity=\".7\"/><path d=\"M100 186c-34-22-42-40-30-52 10-9 24-4 30 8 6-12 20-17 30-8 12 12 4 30-30 52z\" fill=\"#ff7fa3\" transform=\"translate(0,-4) scale(.8) translate(25,38)\"/></svg><h1 id=\"to\" class=\"pacifico\">For You</h1><p class=\"sub\">I made you something small</p></div>\n <div class=\"face back\"><p id=\"msg\">I love you</p><span id=\"from\" class=\"pacifico\">with love</span></div>\n</div></div></div><script>const NAME=\"Mom\", MSG=\"You make every day softer and sunnier.\";\ndocument.getElementById(\"to\").textContent=\"For \"+NAME;\ndocument.getElementById(\"msg\").textContent=MSG;\nconst card=document.getElementById(\"card\");\ncard.onclick=()=>card.classList.toggle(\"open\");\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/card_flip.html"}, {"id": "card_envelope", "emoji": "💌", "title": "Love Letter Envelope", "desc": "Open the envelope to read the letter.", "tags": ["HTML", "CSS", "JS"], "video": "https://youtube.com/shorts/V5Ve5QcORoM", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Love Letter</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.env{position:relative;width:300px;height:190px;cursor:pointer;margin-top:90px}\n.env div{position:absolute}\n.back{inset:0;background:#ff9fbb;border-radius:10px}\n.front{inset:0;background:#ffc2d4;border-radius:10px;clip-path:polygon(0 0,50% 58%,100% 0,100% 100%,0 100%);z-index:3}\n.flap{left:0;right:0;top:0;height:115px;background:#ff8fb1;clip-path:polygon(0 0,100% 0,50% 100%);transform-origin:top;transition:transform .7s,z-index 0s .35s;z-index:4;border-radius:10px 10px 0 0}\n.seal{left:50%;top:78px;margin-left:-17px;width:34px;height:34px;border-radius:50%;background:#e0668f;color:#fff;display:grid;place-items:center;z-index:5;transition:opacity .3s;position:absolute}\n.letter{left:16px;right:16px;top:12px;height:168px;background:#fffaf5;border-radius:10px;z-index:2;transition:transform .8s .35s cubic-bezier(.3,1.3,.5,1);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:16px;box-shadow:0 4px 10px rgba(0,0,0,.08);font-size:15px;line-height:1.5}\n.letter p{margin:0}.letter b{font-size:20px}\n.env.open .flap{transform:rotateX(180deg);z-index:1}\n.env.open .seal{opacity:0}\n.env.open .letter{transform:translateY(-125px)}\n.tap{margin:0;font-size:13px;opacity:.7}\n</style></head><body><div id=\"stage\"><div class=\"env\" id=\"env\">\n <div class=\"back\"></div>\n <div class=\"letter\"><p id=\"msg\">Dear you,</p><b id=\"from\" class=\"pacifico\">with love</b></div>\n <div class=\"front\"></div>\n <div class=\"flap\"></div>\n <div class=\"seal\">♥</div>\n</div>\n<p class=\"tap\">tap the envelope</p></div><script>const NAME=\"Riya\", MSG=\"Thank you for always being there. You are my favourite person.\";\ndocument.getElementById(\"msg\").textContent=MSG;\ndocument.getElementById(\"from\").textContent=\"— \"+NAME;\nconst env=document.getElementById(\"env\");\nenv.onclick=()=>env.classList.toggle(\"open\");\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/card_envelope.html"}, {"id": "card_popup_heart", "emoji": "💗", "title": "Pop-up Heart", "desc": "Tap the heart and it pops with a surprise.", "tags": ["HTML", "CSS", "JS"], "video": "https://youtube.com/shorts/adEFnUXW7NI", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Pop-up Heart</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.bigheart{font-size:150px;line-height:1;color:#ff7fa3;background:none;border:none;cursor:pointer;animation:beat 1.1s ease-in-out infinite;text-shadow:0 10px 24px rgba(255,127,163,.45);padding:0}\n@keyframes beat{0%,100%{transform:scale(1)}20%{transform:scale(1.14)}40%{transform:scale(1)}60%{transform:scale(1.08)}}\n.msg{margin:0;font-size:19px;font-weight:700;max-width:380px;line-height:1.45;min-height:56px;transition:opacity .4s}\n.mini{position:absolute;left:50%;top:44%;color:#ff8fb1;pointer-events:none;animation:fly 1.4s ease-out forwards}\n@keyframes fly{to{transform:translate(var(--dx),var(--dy)) rotate(var(--r));opacity:0}}\n</style></head><body><div id=\"stage\"><button id=\"heart\" class=\"bigheart\">♥</button>\n<p id=\"msg\" class=\"msg\">Tap the heart</p></div><script>const MSG=\"I love you more than pizza. Yes, really.\";\nconst heart=document.getElementById(\"heart\"),msg=document.getElementById(\"msg\");\nheart.onclick=()=>{\n  for(let i=0;i<22;i++){\n    const m=document.createElement(\"div\");m.className=\"mini\";m.textContent=\"♥\";\n    const a=Math.random()*6.28,d=90+Math.random()*130;\n    m.style.setProperty(\"--dx\",Math.cos(a)*d+\"px\");m.style.setProperty(\"--dy\",Math.sin(a)*d+\"px\");\n    m.style.setProperty(\"--r\",(Math.random()*120-60)+\"deg\");m.style.fontSize=(14+Math.random()*26)+\"px\";\n    document.getElementById(\"stage\").appendChild(m);setTimeout(()=>m.remove(),1500);\n  }\n  msg.textContent=MSG;\n};\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/card_popup_heart.html"}, {"id": "card_scratch", "emoji": "🎟️", "title": "Scratch Card", "desc": "Scratch with your finger to reveal a message.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Scratch Card</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.wrap{position:relative;width:300px;height:200px;border-radius:20px;overflow:hidden;box-shadow:0 14px 30px rgba(255,143,177,.35),0 0 0 6px #fff}\n.prize{position:absolute;inset:0;background:linear-gradient(160deg,#fffaf5,#ffe3ec);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:20px;font-size:16px;line-height:1.45}\n.prize h2{margin:0;font-size:28px}.prize p{margin:0}\ncanvas{position:absolute;inset:0;cursor:crosshair;touch-action:none;transition:opacity .8s}\n.tap{margin:0;font-size:13px;opacity:.7}\n</style></head><body><div id=\"stage\"><div class=\"wrap\">\n <div class=\"prize\"><h2 id=\"to\" class=\"pacifico\">You are loved</h2><p id=\"msg\">A secret message</p></div>\n <canvas id=\"c\" width=\"300\" height=\"200\"></canvas>\n</div>\n<p class=\"tap\">scratch with your finger</p></div><script>const NAME=\"You are loved\", MSG=\"Surprise! Dinner is on me tonight.\";\ndocument.getElementById(\"to\").textContent=NAME;\ndocument.getElementById(\"msg\").textContent=MSG;\nconst c=document.getElementById(\"c\"),x=c.getContext(\"2d\");\nlet g=x.createLinearGradient(0,0,300,200);g.addColorStop(0,\"#ff9fbb\");g.addColorStop(1,\"#ffc2d4\");\nx.fillStyle=g;x.fillRect(0,0,300,200);\nx.fillStyle=\"rgba(255,255,255,.55)\";x.font=\"22px serif\";\nfor(let i=0;i<7;i++)for(let j=0;j<5;j++)x.fillText(\"♥\",14+i*44+(j%2)*18,34+j*40);\nx.fillStyle=\"#fff\";x.font=\"700 26px Quicksand,sans-serif\";x.textAlign=\"center\";x.fillText(\"scratch me\",150,108);\nlet down=false,n=0;\nc.onmousedown=()=>down=true;window.onmouseup=()=>down=false;\nc.ontouchstart=()=>down=true;c.ontouchend=()=>down=false;\nfunction scratch(e){\n  if(!down)return;const r=c.getBoundingClientRect(),p=e.touches?e.touches[0]:e;\n  const k=300/r.width;\n  x.globalCompositeOperation=\"destination-out\";x.beginPath();x.arc((p.clientX-r.left)*k,(p.clientY-r.top)*k,22,0,7);x.fill();\n  if(++n%10==0){const d=x.getImageData(0,0,300,200).data;let t=0;for(let i=3;i<d.length;i+=64)if(d[i]<20)t++;\n    if(t/(d.length/64)>.5){c.style.opacity=0;}}\n}\nc.onmousemove=scratch;c.ontouchmove=e=>{e.preventDefault();scratch(e)};\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/card_scratch.html"}, {"id": "card_birthday", "emoji": "🎂", "title": "Birthday Card", "desc": "Blow out the candle and make a wish. Change the name in the code!", "tags": ["HTML", "CSS", "JS"], "video": "https://youtube.com/shorts/F4_pMBwtmSM", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Birthday Card</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\nh1{margin:0;font-size:34px;animation:jump 1.6s ease-in-out infinite}\n@keyframes jump{50%{transform:translateY(-6px)}}\n#flame{transform-origin:95px 33px;animation:flick .25s ease-in-out infinite alternate}\n@keyframes flick{to{transform:scale(.88,1.1) rotate(3deg)}}\n.msg{margin:0;font-size:17px;font-weight:700;max-width:380px;line-height:1.4;min-height:44px}\n#blow{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\n#conf{position:absolute;inset:0;pointer-events:none}\n</style></head><body><div id=\"stage\"><h1 id=\"to\" class=\"pacifico\">Happy Birthday!</h1>\n<svg id=\"cake\" width=\"190\" height=\"170\" viewBox=\"0 0 190 170\">\n <rect x=\"30\" y=\"100\" width=\"130\" height=\"55\" rx=\"10\" fill=\"#ffc2d4\"/>\n <rect x=\"48\" y=\"62\" width=\"94\" height=\"42\" rx=\"10\" fill=\"#ffd9c7\"/>\n <path d=\"M30 108q10 14 21 0t21 0 21 0 21 0 21 0 14 0\" fill=\"#fff\" stroke=\"#fff\" stroke-width=\"6\" stroke-linejoin=\"round\"/>\n <rect x=\"91\" y=\"30\" width=\"8\" height=\"34\" rx=\"3\" fill=\"#ff8fb1\"/>\n <ellipse id=\"flame\" cx=\"95\" cy=\"22\" rx=\"7\" ry=\"11\" fill=\"#ffc94d\"/>\n</svg>\n<p id=\"msg\" class=\"msg\">Make a wish</p>\n<button id=\"blow\">blow the candle</button>\n<canvas id=\"conf\" width=\"540\" height=\"480\"></canvas></div><script>const NAME=\"Rhea\", MSG=\"Another year, another reason to celebrate you.\";\ndocument.getElementById(\"to\").textContent=\"Happy Birthday \"+NAME+\"!\";\nconst cv=document.getElementById(\"conf\"),x=cv.getContext(\"2d\"),COL=[\"#ff8fb1\",\"#ffd9c7\",\"#ffe28a\",\"#bde6ff\",\"#d7c2ff\"];\nlet bits=[];\ndocument.getElementById(\"blow\").onclick=()=>{\n  document.getElementById(\"flame\").style.display=\"none\";\n  document.getElementById(\"msg\").textContent=MSG;\n  for(let i=0;i<110;i++)bits.push({x:Math.random()*540,y:-Math.random()*300,vy:1.5+Math.random()*2.5,vx:Math.random()*2-1,r:Math.random()*6,vr:Math.random()*.2-.1,c:COL[i%5]});\n};\n(function loop(){x.clearRect(0,0,540,480);\n  for(const b of bits){b.y+=b.vy;b.x+=b.vx;b.r+=b.vr;x.save();x.translate(b.x,b.y);x.rotate(b.r);x.fillStyle=b.c;x.fillRect(-4,-2,9,5);x.restore()}\n  bits=bits.filter(b=>b.y<500);requestAnimationFrame(loop)})();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/card_birthday.html"}]}, {"title": "5 Cute Mini Games", "emoji": "🎮", "desc": "Long video: five little games with HTML, CSS and JavaScript. Play them right here!", "video": "", "short": "", "zip": "downloads/cute_mini_games_code.zip", "items": [{"id": "game_ttt", "emoji": "⭕", "title": "Tic Tac Toe", "desc": "Play against a friend. Hearts and stars instead of X and O.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>WiggleStudioo - Tic Tac Toe</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n.cell{width:92px;height:92px;border-radius:18px;background:#fff;box-shadow:0 6px 14px rgba(255,143,177,.3),0 0 0 3px #ffd6e3 inset;display:grid;place-items:center;font-size:44px;cursor:pointer;color:#e0668f;transition:transform .15s,background .3s}\n#board{display:grid;grid-template-columns:repeat(3,92px);gap:8px}\n.cell:hover{transform:scale(1.06)}\n.cell.win{background:#ffc9db}\n</style></head><body><div id=\"stage\"><h2 class=\"pacifico\">Tic Tac Toe</h2>\n<p id=\"msg\" class=\"note\">♥ goes first</p>\n<div id=\"board\">\n <div class=\"cell\"></div><div class=\"cell\"></div><div class=\"cell\"></div>\n <div class=\"cell\"></div><div class=\"cell\"></div><div class=\"cell\"></div>\n <div class=\"cell\"></div><div class=\"cell\"></div><div class=\"cell\"></div>\n</div>\n<button id=\"again\" class=\"ghost\">play again</button></div><script>const P1=\"☀\", P2=\"☾\";\nconst cells=[...document.querySelectorAll(\".cell\")],msg=document.getElementById(\"msg\");\nconst LINES=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];\nlet board=Array(9).fill(\"\"),turn=P1,over=false;\nmsg.textContent=P1+\" goes first\";\ncells.forEach((c,i)=>c.onclick=()=>{\n  if(board[i]||over)return;\n  board[i]=turn;c.textContent=turn;\n  const w=LINES.find(l=>l.every(k=>board[k]===turn));\n  if(w){w.forEach(k=>cells[k].classList.add(\"win\"));msg.textContent=turn+\" wins!\";over=true;return}\n  if(board.every(Boolean)){msg.textContent=\"It's a draw!\";over=true;return}\n  turn=turn===P1?P2:P1;msg.textContent=turn+\" turn\";\n});\ndocument.getElementById(\"again\").onclick=()=>{board.fill(\"\");cells.forEach(c=>{c.textContent=\"\";c.classList.remove(\"win\")});turn=P1;over=false;msg.textContent=P1+\" goes first\"};\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/game_ttt.html"}, {"id": "game_memory", "emoji": "🃏", "title": "Memory Match", "desc": "Flip the cards and find the pairs.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>WiggleStudioo - Memory Match</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n#grid{display:grid;grid-template-columns:repeat(4,66px);gap:10px}\n.mc{height:66px;border-radius:14px;background:linear-gradient(135deg,#ffb3c9,#ff8fb1);display:grid;place-items:center;font-size:30px;color:transparent;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.4);transition:transform .2s,background .2s}\n.mc:hover{transform:scale(1.05)}\n.mc.up,.mc.done{background:#fff;color:#e0668f;box-shadow:0 0 0 3px #ffd6e3 inset}\n.mc.done{background:#ffe3ec}\n</style></head><body><div id=\"stage\"><h2 class=\"pacifico\">Memory Match</h2>\n<p class=\"note\">find the pairs · moves: <b id=\"moves\">0</b></p>\n<div id=\"grid\">\n <div class=\"mc\"></div><div class=\"mc\"></div><div class=\"mc\"></div><div class=\"mc\"></div>\n <div class=\"mc\"></div><div class=\"mc\"></div><div class=\"mc\"></div><div class=\"mc\"></div>\n <div class=\"mc\"></div><div class=\"mc\"></div><div class=\"mc\"></div><div class=\"mc\"></div>\n</div>\n<p id=\"msg\" class=\"note\">&nbsp;</p>\n<button id=\"again\" class=\"ghost\">shuffle</button></div><script>const SYMBOLS=\"♠ ♣ ♦ ♞ ☂ ☃\".split(\" \");\nconst cards=[...document.querySelectorAll(\".mc\")],moves=document.getElementById(\"moves\"),msg=document.getElementById(\"msg\");\nlet first=null,lock=false,count=0;\nfunction deal(){\n  const deck=[...SYMBOLS,...SYMBOLS].sort(()=>Math.random()-.5);\n  cards.forEach((c,i)=>{c.dataset.s=deck[i];c.textContent=deck[i];c.className=\"mc\"});\n  first=null;lock=false;count=0;moves.textContent=0;msg.textContent=\"\\u00a0\";\n}\ncards.forEach(c=>c.onclick=()=>{\n  if(lock||c===first||c.classList.contains(\"done\"))return;\n  c.classList.add(\"up\");\n  if(!first){first=c;return}\n  moves.textContent=++count;\n  if(first.dataset.s===c.dataset.s){\n    first.classList.add(\"done\");c.classList.add(\"done\");first=null;\n    if(cards.every(x=>x.classList.contains(\"done\")))msg.textContent=\"You found them all!\";\n  }else{\n    lock=true;\n    setTimeout(()=>{first.classList.remove(\"up\");c.classList.remove(\"up\");first=null;lock=false},700);\n  }\n});\ndocument.getElementById(\"again\").onclick=deal;deal();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/game_memory.html"}, {"id": "game_mole", "emoji": "🔨", "title": "Whack-a-Mole", "desc": "Tap the moles before they hide.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>WiggleStudioo - Whack-a-Mole</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n#field{display:grid;grid-template-columns:repeat(3,110px);gap:12px}\n.hole{height:92px;border-radius:50% 50% 18px 18px;background:#e9c9b8;box-shadow:inset 0 -10px 0 #d9ae98;overflow:hidden;position:relative;cursor:pointer}\n.mole{position:absolute;left:18%;right:18%;bottom:-100%;height:80%;border-radius:50% 50% 30% 30%;background:#c98f6b;transition:bottom .15s;color:#3a2250;font-weight:700;padding-top:14px}\n.mole::before{content:\"• •\";letter-spacing:10px;font-size:22px}\n.hole.up .mole{bottom:0}\n.hole.hit .mole{background:#ff9eb8}\n</style></head><body><div id=\"stage\"><h2 class=\"pacifico\">Whack-a-Mole</h2>\n<p class=\"note\">score: <b id=\"score\">0</b> · time: <b id=\"time\">10</b></p>\n<div id=\"field\">\n<div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div><div class=\"hole\"><div class=\"mole\"></div></div>\n</div>\n<button id=\"go\">start</button></div><script>const TIME=15, SPEED=650;\nconst holes=[...document.querySelectorAll(\".hole\")],scoreEl=document.getElementById(\"score\"),timeEl=document.getElementById(\"time\"),go=document.getElementById(\"go\");\nlet score=0,left=TIME,loop=null,clock=null;\ntimeEl.textContent=TIME;\nfunction pop(){\n  holes.forEach(h=>h.classList.remove(\"up\",\"hit\"));\n  holes[Math.floor(Math.random()*holes.length)].classList.add(\"up\");\n}\nholes.forEach(h=>h.onclick=()=>{\n  if(!loop||!h.classList.contains(\"up\")||h.classList.contains(\"hit\"))return;\n  h.classList.add(\"hit\");scoreEl.textContent=++score;\n});\ngo.onclick=()=>{\n  if(loop)return;\n  score=0;left=TIME;scoreEl.textContent=0;timeEl.textContent=left;go.textContent=\"playing...\";\n  loop=setInterval(pop,SPEED);\n  clock=setInterval(()=>{\n    timeEl.textContent=--left;\n    if(left<=0){clearInterval(loop);clearInterval(clock);loop=null;holes.forEach(h=>h.classList.remove(\"up\",\"hit\"));go.textContent=\"play again\"}\n  },1000);\n};\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/game_mole.html"}, {"id": "game_guess", "emoji": "🔢", "title": "Guess the Number", "desc": "Higher or lower? Find the secret number.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>WiggleStudioo - Guess the Number</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\n#msg{font-size:18px;opacity:1;min-height:44px;display:flex;align-items:center;max-width:380px}\n.row{display:flex;gap:10px;align-items:center}\ninput{width:120px;padding:12px;border:3px solid #ffd6e3;border-radius:14px;font:inherit;font-size:24px;font-weight:700;text-align:center;color:#7a3b52;outline:none;background:#fff}\ninput:focus{border-color:#ff7fa3}\n</style></head><body><div id=\"stage\"><h2 class=\"pacifico\">Guess the Number</h2>\n<p id=\"msg\" class=\"note\">I'm thinking of a number from 1 to 100</p>\n<div class=\"row\"><input id=\"num\" type=\"number\" min=\"1\" placeholder=\"?\"><button id=\"try\">guess</button></div>\n<p class=\"note\">tries left: <b id=\"left\">10</b></p>\n<button id=\"again\" class=\"ghost\">new game</button></div><script>const MAX=20, TRIES=6;\nconst num=document.getElementById(\"num\"),msg=document.getElementById(\"msg\"),leftEl=document.getElementById(\"left\");\nlet secret,tries;\nfunction start(){\n  secret=Math.floor(Math.random()*MAX)+1;tries=TRIES;\n  leftEl.textContent=tries;num.value=\"\";num.disabled=false;\n  msg.textContent=\"I'm thinking of a number from 1 to \"+MAX;\n}\ndocument.getElementById(\"try\").onclick=()=>{\n  const g=Number(num.value);\n  if(!g||tries<=0||num.disabled)return;\n  tries--;leftEl.textContent=tries;\n  if(g===secret){msg.textContent=\"Yes! It was \"+secret+\"! ♥\";num.disabled=true}\n  else if(tries===0){msg.textContent=\"Out of tries! It was \"+secret;num.disabled=true}\n  else msg.textContent=g>secret?g+\" is too high! Try lower\":g+\" is too low! Try higher\";\n  num.value=\"\";num.focus();\n};\nnum.onkeydown=e=>{if(e.key===\"Enter\")document.getElementById(\"try\").click()};\ndocument.getElementById(\"again\").onclick=start;start();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/game_guess.html"}, {"id": "game_snake", "emoji": "🐍", "title": "Snake", "desc": "Eat the apples and do not hit the wall. Use arrow keys.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>WiggleStudioo - Snake</title><link href=\"https://fonts.googleapis.com/css2?family=Pacifico&family=Quicksand:wght@500;700&display=swap\" rel=\"stylesheet\"><style>html,body{margin:0;height:100%}#stage{position:relative;width:100%;height:100vh;overflow:hidden}</style><style>*{box-sizing:border-box}\n#stage{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;font-family:'Quicksand',sans-serif;color:#7a3b52;text-align:center;background:radial-gradient(circle at 20% 15%,#ffe3ec,transparent 45%),radial-gradient(circle at 85% 85%,#ffe9d9,transparent 45%),#fff0f4}\n.hbg{position:absolute;bottom:-40px;color:#ff8fb1;opacity:.5;animation:rise linear infinite;pointer-events:none}\n@keyframes rise{to{transform:translateY(-110vh) rotate(25deg);opacity:0}}\n.pacifico{font-family:'Pacifico',cursive;font-weight:400;color:#e0668f}\n.note{margin:0;font-size:13px;font-weight:700;opacity:.75}\nbutton{font:inherit;font-weight:700;color:#fff;background:#ff8fb1;border:none;border-radius:20px;padding:9px 22px;cursor:pointer;box-shadow:0 6px 14px rgba(255,143,177,.45)}\nbutton.ghost{background:#fff;color:#e0668f;box-shadow:0 0 0 2px #ffc2d4 inset}\nh2{margin:0;font-size:30px}\ncanvas{background:#fff;border-radius:18px;box-shadow:0 8px 20px rgba(255,143,177,.35),0 0 0 4px #ffd6e3 inset}\n</style></head><body><div id=\"stage\"><h2 class=\"pacifico\">Snake</h2>\n<p class=\"note\">score: <b id=\"score\">0</b> · use the arrow keys</p>\n<canvas id=\"c\" width=\"320\" height=\"320\"></canvas>\n<p id=\"msg\" class=\"note\">press an arrow key to start</p></div><script>const SPEED=90, COLOR=\"#a98bff\";\nconst cv=document.getElementById(\"c\"),ctx=cv.getContext(\"2d\"),N=16,SZ=20;\nconst scoreEl=document.getElementById(\"score\"),msg=document.getElementById(\"msg\");\nconst KEYS={ArrowUp:{x:0,y:-1},ArrowDown:{x:0,y:1},ArrowLeft:{x:-1,y:0},ArrowRight:{x:1,y:0}};\nlet snake,dir,last,food,score,timer=null,over=false;\nfunction reset(){\n  snake=[{x:8,y:8},{x:7,y:8},{x:6,y:8}];dir={x:1,y:0};last=dir;score=0;over=false;\n  scoreEl.textContent=0;msg.textContent=\"press an arrow key to start\";placeFood();draw();\n}\nfunction placeFood(){\n  do{food={x:Math.floor(Math.random()*N),y:Math.floor(Math.random()*N)}}\n  while(snake.some(s=>s.x===food.x&&s.y===food.y));\n}\nfunction step(){\n  last=dir;\n  const head={x:snake[0].x+dir.x,y:snake[0].y+dir.y};\n  if(head.x<0||head.y<0||head.x>=N||head.y>=N||snake.some(s=>s.x===head.x&&s.y===head.y)){\n    clearInterval(timer);timer=null;over=true;msg.textContent=\"Game over! press an arrow to play again\";return;\n  }\n  snake.unshift(head);\n  if(head.x===food.x&&head.y===food.y){scoreEl.textContent=++score;placeFood()}else snake.pop();\n  draw();\n}\nfunction draw(){\n  ctx.clearRect(0,0,320,320);\n  ctx.fillStyle=\"#ff5f8f\";ctx.font=\"18px sans-serif\";ctx.textAlign=\"center\";ctx.textBaseline=\"middle\";\n  ctx.fillText(\"♥\",food.x*SZ+10,food.y*SZ+11);\n  snake.forEach((s,i)=>{ctx.fillStyle=i?COLOR:\"#e0668f\";ctx.beginPath();ctx.roundRect(s.x*SZ+1,s.y*SZ+1,SZ-2,SZ-2,6);ctx.fill()});\n}\naddEventListener(\"keydown\",e=>{\n  const d=KEYS[e.key];if(!d)return;e.preventDefault();\n  if(over)reset();\n  if(d.x===-last.x&&d.y===-last.y)return;\n  dir=d;\n  if(!timer){timer=setInterval(step,SPEED);msg.textContent=\"\\u00a0\"}\n});\nreset();\nconst S=document.getElementById(\"stage\");\nfunction bgHeart(){const h=document.createElement(\"div\");h.className=\"hbg\";h.textContent=\"♥\";h.style.left=Math.random()*100+\"%\";h.style.fontSize=(12+Math.random()*22)+\"px\";h.style.animationDuration=(5+Math.random()*5)+\"s\";S.appendChild(h);setTimeout(()=>h.remove(),10500)}\nfor(let i=0;i<10;i++)setTimeout(bgHeart,i*300);setInterval(bgHeart,650);\n</script></body></html>", "dl": "demos/game_snake.html"}]}, {"title": "Cute Bakery Website", "emoji": "🧁", "desc": "Long video: build a whole bakery website from an empty folder, with a working cart counter.", "video": "", "short": "", "zip": "downloads/bakery_website_code.zip", "items": [{"title": "Cute Bakery Website", "emoji": "🧁", "desc": "3 files plus pictures: index.html, style.css, script.js, img folder.", "tags": ["HTML", "CSS", "JS"], "img": "img/bakery.jpg", "zip": "downloads/bakery_website_code.zip", "video": ""}]}, {"title": "Love Letter That Types Itself", "emoji": "💌", "desc": "Long video: an envelope made with CSS opens and the letter types itself. Add ?to=YourName to the link!", "video": "", "short": "", "zip": "downloads/love_letter_code.zip", "items": [{"id": "loveletter", "emoji": "💌", "title": "Love Letter", "desc": "Press Open. The envelope opens, the message types, hearts fall.", "tags": ["HTML", "CSS", "JS"], "video": "", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\"\n    content=\"width=device-width\">\n  <title>A Letter For You</title>\n  <link rel=\"stylesheet\" href=\n  \"https://fonts.googleapis.com/css?family=Caveat\">\n  <style>\n:root {\n  --pink: #ffb3cb;\n  --rose: #ff85ab;\n  --berry: #c2255c;\n  --paper: #fffdf7;\n}\n* { box-sizing: border-box; margin: 0; }\nbody {\n  font-family: \"Segoe UI\", sans-serif;\n  background: linear-gradient(#ffd6e5, #ffe9d6);\n  min-height: 100vh;\n  color: #6b4256;\n}\n\n.stage {\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 50px;\n  padding-top: 120px;\n}\n\n.to {\n  font: 60px Caveat, cursive;\n  color: var(--berry);\n}\n#open {\n  background: var(--berry);\n  color: #fff;\n  border: 0;\n  padding: 14px 36px;\n  border-radius: 30px;\n  font-size: 18px;\n  cursor: pointer;\n}\n#open:hover { background: var(--rose); }\n\n.envelope {\n  position: relative;\n  width: 360px;\n  height: 240px;\n  background: var(--pink);\n  border-radius: 8px;\n  box-shadow: 0 16px 36px #c2255c40;\n}\n\n.pocket {\n  position: absolute;\n  inset: 0;\n  background: #ff9ec0;\n  border-radius: 8px;\n  clip-path: polygon(0 0, 50% 55%, 100% 0,\n    100% 100%, 0 100%);\n  z-index: 2;\n}\n.flap {\n  position: absolute;\n  top: 0;\n  width: 100%;\n  height: 60%;\n  background: var(--rose);\n  clip-path: polygon(0 0, 100% 0, 50% 100%);\n  transform-origin: top;\n  z-index: 3;\n}\n\n.letter {\n  position: absolute;\n  left: 20px;\n  right: 20px;\n  top: 14px;\n  height: 210px;\n  background: var(--paper);\n  border-radius: 6px;\n  padding: 24px 20px;\n  z-index: 1;\n}\n#text { font: 26px/1.3 Caveat, cursive; }\n\n.seal {\n  position: absolute;\n  left: 50%;\n  top: 58%;\n  width: 54px;\n  height: 54px;\n  margin: -27px 0 0 -27px;\n  border-radius: 50%;\n  background: var(--berry);\n  color: #fff;\n  display: grid;\n  place-items: center;\n  font-size: 28px;\n  z-index: 4;\n}\n\n.flap { transition: transform .6s; }\n.seal { transition: opacity .3s; }\n\n.open .flap {\n  transform: rotateX(180deg);\n  z-index: 0;\n}\n.open .seal { opacity: 0; }\n\n.letter { transition: transform .9s .5s; }\n\n.open .letter {\n  transform: translateY(-190px) scale(1.15);\n}\n.to { transition: opacity .5s; }\n.stage:has(.open) .to { opacity: 0; }\n\n.petal {\n  position: fixed;\n  top: -40px;\n  color: var(--rose);\n  animation: fall linear forwards;\n  pointer-events: none;\n}\n@keyframes fall {\n  to {\n    transform: translateY(110vh) rotate(360deg);\n  }\n}\n\n#text::after {\n  content: \"|\";\n  animation: blink 1s infinite;\n}\n@keyframes blink { 50% { opacity: 0; } }\n\n.seal { animation: beat 1.4s infinite; }\n@keyframes beat {\n  50% { transform: scale(1.15); }\n}\n\n</style>\n  <script>\nwindow.addEventListener(\"DOMContentLoaded\",()=>{\nconst env = document.getElementById(\"env\");\nconst btn = document.getElementById(\"open\");\n\nbtn.onclick = () => {\n  env.classList.add(\"open\");\n  btn.style.display = \"none\";\n  setTimeout(type, 1400);\n};\n\nconst text = document.getElementById(\"text\");\nconst msg = [\n  \"Thank you for being you.\",\n  \"You make ordinary days feel\",\n  \"like tiny celebrations.\",\n  \"Never forget how loved you are.\"\n].join(\" \");\n\nlet i = 0;\nfunction type() {\n  text.textContent = msg.slice(0, ++i);\n  if (i < msg.length) setTimeout(type, 55);\n}\n\nconst to = new URLSearchParams(location.search)\n  .get(\"to\");\n\nif (to) {\n  document.getElementById(\"to\").textContent =\n    \"A letter for \" + to;\n}\n\nfunction petal() {\n  const p = document.createElement(\"div\");\n  const r = Math.random();\n  p.className = \"petal\";\n  p.textContent = \"\\u2665\";\n  p.style.left = r * 100 + \"vw\";\n  p.style.fontSize = 14 + r * 18 + \"px\";\n  p.style.animationDuration = 4 + r * 4 + \"s\";\n  document.body.append(p);\n  setTimeout(() => p.remove(), 8000);\n}\nsetInterval(petal, 350);\n\n});\n</script>\n</head>\n<body>\n  <main class=\"stage\">\n    <h1 class=\"to\" id=\"to\">A letter for you</h1>\n    <div class=\"envelope\" id=\"env\">\n      <div class=\"flap\"></div>\n      <div class=\"letter\">\n        <p id=\"text\"></p>\n      </div>\n      <div class=\"pocket\"></div>\n      <div class=\"seal\">&#9829;</div>\n    </div>\n    <button id=\"open\">Open it</button>\n  </main>\n</body>\n</html>\n", "dl": "demos/loveletter.html"}]}, {"title": "Python Art", "emoji": "🐍", "desc": "Long video: can you guess what this code draws? Run it yourself and see all the pictures.", "video": "", "short": "", "zip": "", "items": [{"id": "guess_the_code", "file": "downloads/guess_the_code.py", "emoji": "🐍", "title": "Can You Guess What This Code Draws?", "desc": "11 drawings in one file: circle, spiral, flower, stars, waves, mandala, tree, snowflake, galaxy, lightning, aurora. Needs: pip install pillow numpy", "tags": ["Python"], "img": "img/guess_the_code.jpg", "dl": "downloads/guess_the_code.py", "video": "", "code": "# Can You Guess What This Code Draws?  -  WiggleStudioo\n# Run:  pip install pillow numpy   then   python guess_the_code.py\n# It saves 11 pictures (round01_circle.png ...) in the same folder.\n# Note: the video shows short, simplified lines. This is the full runnable version.\nimport math, random\nimport numpy as np\nfrom math import cos, sin, radians, pi, exp, log\nfrom PIL import Image, ImageDraw\n\nW = H = 600\ncx, cy = W / 2, H / 2\nBG = (12, 10, 30)\n\ndef canvas():\n    img = Image.new(\"RGB\", (W, H), BG)\n    return img, ImageDraw.Draw(img)\n\ndef dot(d, x, y, r=3, color=(255, 170, 215)):\n    d.ellipse((x - r, y - r, x + r, y + r), fill=color)\n\ndef save(img, n, name):\n    img.save(f\"round{n:02d}_{name}.png\")\n    print(\"saved\", f\"round{n:02d}_{name}.png\")\n\n# 1. circle\nimg, d = canvas()\nfor deg in range(360):\n    x = cx + 200 * cos(radians(deg))\n    y = cy + 200 * sin(radians(deg))\n    dot(d, x, y)\nsave(img, 1, \"circle\")\n\n# 2. spiral\nimg, d = canvas()\nfor i in range(900):\n    r = i * 0.32\n    a = i * 0.1\n    dot(d, cx + r * cos(a), cy + r * sin(a), 2.5, (150, 220, 255))\nsave(img, 2, \"spiral\")\n\n# 3. flower\nimg, d = canvas()\nfor deg in range(720):\n    a = radians(deg)\n    r = 230 * cos(6 * a)\n    dot(d, cx + r * cos(a), cy + r * sin(a), 2.5, (255, 140, 200))\nsave(img, 3, \"flower\")\n\n# 4. stars\nimg, d = canvas()\nfor i in range(300):\n    x = random.uniform(0, W)\n    y = random.uniform(0, H)\n    size = random.uniform(1, 4)\n    dot(d, x, y, size / 2 + .5, (255, 245, 220))\nsave(img, 4, \"stars\")\n\n# 5. waves\nimg, d = canvas()\ncols = [(90, 60, 200), (80, 100, 220), (70, 140, 230), (80, 180, 235), (110, 215, 240), (170, 240, 250)]\nfor k in range(6):\n    for x in range(W):\n        y = 250 + k * 45 + 20 * sin(x * .02 + k)\n        d.line((x, y, x, H), fill=cols[k])\nsave(img, 5, \"waves\")\n\n# 6. mandala\nimg, d = canvas()\ndef petal(angle, size, color):\n    pts = []\n    for t in range(0, 361, 10):\n        u = radians(t)\n        px, py = size * (1 + cos(u)) / 2, size * .22 * sin(u)\n        pts.append((cx + px * cos(angle) - py * sin(angle), cy + px * sin(angle) + py * cos(angle)))\n    d.polygon(pts, outline=color)\nfor ring in range(6, 0, -1):\n    for k in range(12):\n        angle = k * 2 * pi / 12 + ring * .13\n        petal(angle, 60 + ring * 38, (255, 120 + ring * 20, 200))\nsave(img, 6, \"mandala\")\n\n# 7. tree\nimg, d = canvas()\ndef branch(x, y, a, L, depth):\n    if depth == 0:\n        return\n    x2 = x + L * cos(a)\n    y2 = y - L * sin(a)\n    d.line((x, y, x2, y2), fill=(120 + depth * 15, 255 - depth * 12, 170), width=max(1, depth))\n    branch(x2, y2, a + .4, L * .75, depth - 1)\n    branch(x2, y2, a - .4, L * .75, depth - 1)\nbranch(cx, H - 20, pi / 2, 120, 9)\nsave(img, 7, \"tree\")\n\n# 8. snowflake\nimg, d = canvas()\ndef arm(x, y, a, length, depth):\n    if depth == 0:\n        return\n    x2, y2 = x + length * cos(a), y + length * sin(a)\n    d.line((x, y, x2, y2), fill=(190, 230, 255), width=2)\n    mx, my = x + length * .55 * cos(a), y + length * .55 * sin(a)\n    arm(mx, my, a + radians(60), length / 2.4, depth - 1)\n    arm(mx, my, a - radians(60), length / 2.4, depth - 1)\n    arm(x2, y2, a, length / 2.6, depth - 1)\nfor k in range(6):\n    arm(cx, cy, radians(60 * k), 250, 4)\nsave(img, 8, \"snowflake\")\n\n# 9. galaxy\nn = 90000\nr = np.random.exponential(.28, n)\narm_off = np.random.randint(0, 2, n) * pi\ntheta = 3.4 * np.log(1 + 3.2 * r) + arm_off + np.random.normal(0, .12, n)\nx = r * np.cos(theta)\ny = r * np.sin(theta) * .46\nmix = np.exp(-5 * r)[:, None]\ncol = np.array([110, 150, 255]) * (1 - mix) + np.array([255, 215, 130]) * mix\nacc = np.zeros((H, W, 3))\npx = (cx + x * 300).astype(int)\npy = (cy + y * 300).astype(int)\nok = (px >= 0) & (px < W) & (py >= 0) & (py < H)\nnp.add.at(acc, (py[ok], px[ok]), col[ok] * .6)\nimg = Image.fromarray(np.clip(acc + np.array(BG), 0, 255).astype(np.uint8))\nsave(img, 9, \"galaxy\")\n\n# 10. lightning\nimg, d = canvas()\ndef bolt(p, q, depth, spread):\n    if depth == 0:\n        d.line((p[0], p[1], q[0], q[1]), fill=(220, 235, 255), width=2)\n        return\n    mid = ((p[0] + q[0]) / 2 + random.uniform(-spread, spread), (p[1] + q[1]) / 2 + random.uniform(-spread / 4, spread / 4))\n    bolt(p, mid, depth - 1, spread / 2)\n    bolt(mid, q, depth - 1, spread / 2)\nbolt((cx, 20), (cx + 40, H - 20), 8, 160)\nsave(img, 10, \"lightning\")\n\n# 11. aurora\nyy, xx = np.mgrid[0:H, 0:W].astype(float)\nim = np.zeros((H, W, 3)) + np.array(BG, float)\npalette = [(60, 255, 170), (80, 230, 200), (120, 190, 255), (170, 140, 255), (230, 120, 220)]\nfor k in range(5):\n    base = 150 + 26 * k + 44 * np.sin(xx / 80 + k)\n    dd = (base - yy) / 170\n    glow = np.exp(-dd * 2) * (dd > 0)\n    im += glow[..., None] * np.array(palette[k]) * .55\nimg = Image.fromarray(np.clip(im, 0, 255).astype(np.uint8))\nsave(img, 11, \"aurora\")\n"}]}]};
